//! Publication manifest: a portable, user-saved record of rights, hashes,
//! provenance and delivery targets. It is generated by the app, but the save
//! path is chosen explicitly and the write is atomic.

use std::path::{Path, PathBuf};

use serde_json::Value;
use tauri::{AppHandle, State};
use tauri_plugin_dialog::DialogExt;
use uuid::Uuid;

use crate::projects::service::{ProjectError, ProjectErrorCode};
use crate::state::AppState;

const MAX_MANIFEST_BYTES: usize = 1_000_000;
const FORBIDDEN_KEYS: &[&str] = &[
    "api_key",
    "apikey",
    "access_token",
    "refresh_token",
    "secret",
    "password",
    "authorization",
    "auth_token",
    "bearer_token",
    "cookie",
    "private_key",
];

fn normalized_key(key: &str) -> String {
    key.chars()
        .filter(|character| character.is_ascii_alphanumeric())
        .flat_map(char::to_lowercase)
        .collect()
}

fn contains_forbidden_key(value: &Value) -> bool {
    match value {
        Value::Object(map) => map.iter().any(|(key, child)| {
            FORBIDDEN_KEYS
                .iter()
                .any(|forbidden| normalized_key(key) == normalized_key(forbidden))
                || contains_forbidden_key(child)
        }),
        Value::Array(items) => items.iter().any(contains_forbidden_key),
        _ => false,
    }
}

fn validate_manifest(manifest: &Value) -> Result<String, ProjectError> {
    if !manifest.is_object() {
        return Err(ProjectError::message(
            ProjectErrorCode::InvalidProject,
            "el manifiesto debe ser un objeto JSON",
        ));
    }
    if contains_forbidden_key(manifest) {
        return Err(ProjectError::message(
            ProjectErrorCode::InvalidProject,
            "el manifiesto no puede contener claves ni credenciales",
        ));
    }
    let text = serde_json::to_string_pretty(manifest).map_err(|_| {
        ProjectError::message(
            ProjectErrorCode::InvalidProject,
            "no se pudo serializar el manifiesto",
        )
    })?;
    if text.len() > MAX_MANIFEST_BYTES {
        return Err(ProjectError::message(
            ProjectErrorCode::InvalidProject,
            "el manifiesto supera 1 MB",
        ));
    }
    Ok(text)
}

fn ensure_json_extension(mut path: PathBuf) -> PathBuf {
    if !path
        .extension()
        .map(|value| value.eq_ignore_ascii_case("json"))
        .unwrap_or(false)
    {
        path.set_extension("json");
    }
    path
}

fn canonical_candidate(path: &Path) -> Option<PathBuf> {
    if path.exists() {
        return path.canonicalize().ok();
    }
    let parent = path.parent()?.canonicalize().ok()?;
    Some(parent.join(path.file_name()?))
}

pub(crate) fn ensure_path_is_safe(
    project_path: &Path,
    root: &Path,
    output: &Path,
) -> Result<(), ProjectError> {
    let Some(output) = canonical_candidate(output) else {
        return Err(ProjectError::message(
            ProjectErrorCode::Io,
            "la carpeta de destino no existe",
        ));
    };
    let project = project_path
        .canonicalize()
        .unwrap_or_else(|_| project_path.to_path_buf());
    if output == project {
        return Err(ProjectError::message(
            ProjectErrorCode::InvalidProject,
            "el manifiesto no puede sobrescribir el proyecto",
        ));
    }
    let opened = crate::projects::service::open_project(project_path)?;
    for asset in opened.project["assets"]
        .as_array()
        .cloned()
        .unwrap_or_default()
    {
        let Some(relative) = asset["source"]["path"].as_str() else {
            continue;
        };
        if let Ok(asset_path) = crate::media::resolve_inside_root(root, relative) {
            let asset_path = asset_path
                .canonicalize()
                .unwrap_or_else(|_| asset_path.clone());
            if output == asset_path {
                return Err(ProjectError::message(
                    ProjectErrorCode::InvalidProject,
                    "el manifiesto no puede sobrescribir un medio del proyecto",
                ));
            }
        }
    }
    Ok(())
}

#[tauri::command]
pub async fn save_publication_manifest(
    app: AppHandle,
    state: State<'_, AppState>,
    manifest: Value,
) -> Result<Option<String>, ProjectError> {
    let session = state.require_session()?;
    let text = validate_manifest(&manifest)?;
    let Some(picked) = app
        .dialog()
        .file()
        .set_title("Guardar manifiesto de publicación")
        .set_directory(&session.root)
        .add_filter("Manifiesto JSON", &["json"])
        .set_file_name("publicacion.json")
        .blocking_save_file()
    else {
        return Ok(None);
    };
    let picked = picked.into_path().map_err(|_| {
        ProjectError::message(ProjectErrorCode::Io, "no se pudo usar la ruta elegida")
    })?;
    let output = ensure_json_extension(picked);
    ensure_path_is_safe(&session.path, &session.root, &output)?;
    let parent = output.parent().ok_or_else(|| {
        ProjectError::message(ProjectErrorCode::Io, "la ruta elegida no tiene carpeta")
    })?;
    let temp = parent.join(format!(".publicacion-{}.tmp", Uuid::new_v4()));
    std::fs::write(&temp, text).map_err(|_| {
        ProjectError::message(
            ProjectErrorCode::Io,
            "no se pudo escribir el manifiesto temporal",
        )
    })?;
    if output.exists() {
        std::fs::remove_file(&output).map_err(|_| {
            let _ = std::fs::remove_file(&temp);
            ProjectError::message(
                ProjectErrorCode::Io,
                "no se pudo reemplazar el manifiesto existente",
            )
        })?;
    }
    std::fs::rename(&temp, &output).map_err(|_| {
        let _ = std::fs::remove_file(&temp);
        ProjectError::message(ProjectErrorCode::Io, "no se pudo publicar el manifiesto")
    })?;
    Ok(Some(output.to_string_lossy().into_owned()))
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn rejects_credentials_anywhere_in_the_manifest() {
        let clean = json!({ "schema": "x", "assets": [{ "sha256": "a" }] });
        assert!(validate_manifest(&clean).is_ok());
        let dirty = json!({ "nested": [{ "Api-Key": "secret" }] });
        assert!(validate_manifest(&dirty).is_err());
    }

    #[test]
    fn rejects_non_objects_and_oversized_documents() {
        assert!(validate_manifest(&json!([1, 2, 3])).is_err());
        let huge = json!({ "data": "x".repeat(MAX_MANIFEST_BYTES + 10) });
        assert!(validate_manifest(&huge).is_err());
    }
}
